from typing import Dict, Any
from domain.entities.invoice import Invoice
from domain.repositories.invoice_repository import InvoiceRepository
from domain.services.stripe_service import StripeService
from domain.errors.invoice_errors import InvalidAmountError, InvoiceCreationError
from application.dtos.invoice_dto import CreateInvoiceRequest, CreateInvoiceResponse
from application.errors.application_errors import ApplicationError

class CreateInvoiceUseCase:
    def __init__(self, invoice_repository: InvoiceRepository, stripe_service: StripeService):
        self.invoice_repository = invoice_repository
        self.stripe_service = stripe_service

    def execute(self, request: CreateInvoiceRequest) -> Result[CreateInvoiceResponse, ApplicationError]:
        # Validate input
        if request.amount <= 0:
            return Result.failure(InvalidAmountError())

        # Create invoice entity
        invoice = Invoice(
            customer_id=request.customer_id,
            amount=request.amount,
            status="UNPAID"
        )

        # Create invoice in repository
        created_invoice_result = self.invoice_repository.create(invoice)
        if created_invoice_result.is_failure:
            return Result.failure(created_invoice_result.error)

        created_invoice = created_invoice_result.value

        # Process payment with Stripe
        charge_result = self.stripe_service.charge(
            amount=int(request.amount * 100),
            currency="usd",
            customer=request.stripe_id
        )

        if charge_result.is_failure:
            # In a real implementation, you might want to rollback the invoice creation
            return Result.failure(charge_result.error)

        # Return success response
        return Result.success(CreateInvoiceResponse(
            invoice_id=created_invoice.id,
            status=created_invoice.status
        ))

