import { IPaymentGateway } from '../../domain/ports/IPaymentGateway';

/**
 * Process payment use case
 */
export class ProcessPaymentUseCase {
  constructor(private readonly paymentGateway: IPaymentGateway) {}

  async execute(request: PaymentRequest): Promise<Result<PaymentResponse, PaymentError>> {
    try {
      // Validate input
      const validation = this.validatePaymentRequest(request);
      if (validation.isError) {
        return validation;
      }

      // Delegate to payment gateway
      return await this.paymentGateway.processPayment(request);
    } catch (error) {
      return Result.error({
        type: 'PaymentGatewayError',
        message: 'Unexpected error processing payment',
        provider: 'Stripe'
      });
    }
  }

  private validatePaymentRequest(request: PaymentRequest): Result<void, PaymentValidationError> {
    if (!request.customerId) {
      return Result.error({
        type: 'PaymentValidationError',
        message: 'Customer ID is required',
        field: 'customerId'
      });
    }

    if (request.amount <= 0) {
      return Result.error({
        type: 'PaymentValidationError',
        message: 'Amount must be greater than zero',
        field: 'amount'
      });
    }

    if (!request.paymentMethodId) {
      return Result.error({
        type: 'PaymentValidationError',
        message: 'Payment method ID is required',
        field: 'paymentMethodId'
      });
    }

    return Result.success(undefined);
  }
}

