// Domain/ValueObjects/Email.ts
import { Result, Ok, Err } from '../Result';
import { ValidationError } from '../Errors/ValidationError';

export class Email {
  private constructor(public readonly value: string) {}

  static create(email: string): Result<Email, ValidationError> {
    // Check if email is empty or null
    if (!email || typeof email !== 'string') {
      return Err(new ValidationError('Email cannot be empty'));
    }

    // Normalize to lowercase
    const normalizedEmail = email.toLowerCase().trim();

    // Check if email is empty after normalization
    if (normalizedEmail.length === 0) {
      return Err(new ValidationError('Email cannot be empty'));
    }

    // Validate email format using regex
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(normalizedEmail)) {
      return Err(new ValidationError('Invalid email format'));
    }

    return Ok(new Email(normalizedEmail));
  }

  equals(other: Email): boolean {
    return this.value === other.value;
  }

  toString(): string {
    return this.value;
  }
}

// Domain/Result.ts
export type Result<T, E> = Ok<T, E> | Err<T, E>;

export class Ok<T, E> {
  constructor(public readonly value: T) {}

  isOk(): this is Ok<T, E> {
    return true;
  }

  isErr(): this is Err<T, E> {
    return false;
  }
}

export class Err<T, E> {
  constructor(public readonly error: E) {}

  isOk(): this is Ok<T, E> {
    return false;
  }

  isErr(): this is Err<T, E> {
    return true;
  }
}

export function Ok<T, E>(value: T): Result<T, E> {
  return new Ok(value);
}

export function Err<T, E>(error: E): Result<T, E> {
  return new Err(error);
}
```

This implementation follows Clean Architecture principles:

1. **Value Object**: `Email` is immutable and represents a single email value
2. **Invariant Validation**:
   - Ensures email is not empty
   - Validates email format using regex
   - Normalizes to lowercase
3. **Result Pattern**: Returns `Result<Email, ValidationError>` for safe error handling
4. **Dependency Rule Compliance**: 
   - Domain layer (Email, ValidationError) doesn't depend on external libraries
   - No framework or infrastructure dependencies
5. **Type Safety**: 
   - Uses strict typing with no `any` types
   - Dedicated error types
   - Type guards for Result pattern
6. **SOLID Principles**:
   - Single Responsibility: Email handles only email validation and representation
   - Open/Closed: Can be extended without modifying existing code
   - Liskov Substitution: Email can be used wherever a string is expected (via toString)
   - Interface Segregation: Minimal interface with clear responsibilities
   - Dependency Inversion: Depends on abstractions (Result, ValidationError) rather than concrete implementations

The implementation ensures that:
- All emails are normalized to lowercase
- Empty emails are rejected
- Invalid email formats are rejected
- The value object is immutable
- Error handling is explicit and type-safe

