import { OrderRepository } from '../../domain/repositories/OrderRepository';
import { Order } from '../../domain/models/Order';
import { MongoClient, Collection } from 'mongodb';

export class MongoOrderRepository implements OrderRepository {
  private collection: Collection<Order> | null = null;

  constructor(private readonly client: MongoClient, private readonly dbName: string) {}

  async initialize(): Promise<void> {
    const db = this.client.db(this.dbName);
    this.collection = db.collection<Order>('orders');
  }

  async save(order: Order): Promise<Order> {
    if (!this.collection) {
      throw new Error('Repository not initialized');
    }

    const result = await this.collection.insertOne(order);
    return { ...order, _id: result.insertedId };
  }
}

