export class ProcessOrderUseCaseImpl implements ProcessOrderUseCase {
  constructor(
    private readonly taxCalculator: TaxCalculator,
    private readonly orderRepository: OrderRepository
  ) {}

  async execute(orderData: Order): Promise<Result<Order, OrderError>> {
    // Validate order
    const validation = this.validateOrder(orderData);
    if (validation.isError()) {
      return error(validation.error);
    }

    // Calculate tax
    const tax = this.taxCalculator.calculateTax(orderData);
    const orderWithTax = { ...orderData, tax };

    // Save order
    try {
      await this.orderRepository.save(orderWithTax);
      return ok(orderWithTax);
    } catch (err) {
      return error(new OrderError('Failed to save order'));
    }
  }

  private validateOrder(order: Order): Result<void, InvalidOrderError> {
    if (!order.items || order.items.length === 0) {
      return error(new InvalidOrderError('Order must have at least one item'));
    }
    return ok(undefined);
  }
}

