// Application/UseCases/CancelSubscriptionUseCase.ts
import { Result, Ok, Err } from '../Result';
import { Subscription, SubscriptionError } from '../Entities/Subscription';

export interface CancelSubscriptionRequest {
  subscriptionId: string;
  customerId: string;
  cancelledAt: Date;
}

export interface CancelSubscriptionResponse {
  subscription: Subscription;
  cancelledAt: Date;
}

export class CancelSubscriptionUseCase {
  constructor() {}

  execute(
    request: CancelSubscriptionRequest
  ): Result<CancelSubscriptionResponse, SubscriptionError> {
    try {
      // Validate request
      if (!request.subscriptionId || !request.customerId) {
        return Err(new SubscriptionError(
          'INVALID_REQUEST',
          'Subscription ID and Customer ID are required'
        ));
      }

      // In a real implementation, this would be retrieved from a repository
      // For this example, we'll simulate the domain logic
      const subscription = this.getSubscription(request.subscriptionId);

      // Validate invariant rules
      if (subscription.status === 'expired') {
        return Err(SubscriptionError.AlreadyExpired);
      }

      if (subscription.status !== 'active') {
        return Err(SubscriptionError.InvalidStatus);
      }

      // Perform cancellation
      const updatedSubscription = this.cancelSubscription(
        subscription,
        request.cancelledAt
      );

      return Ok({
        subscription: updatedSubscription,
        cancelledAt: request.cancelledAt
      });
    } catch (error) {
      if (error instanceof SubscriptionError) {
        return Err(error);
      }
      return Err(new SubscriptionError(
        'INTERNAL_ERROR',
        'An unexpected error occurred while cancelling subscription'
      ));
    }
  }

  private getSubscription(subscriptionId: string): Subscription {
    // This would normally come from a repository
    // For demonstration purposes, we'll return a mock subscription
    return {
      id: subscriptionId,
      customerId: 'customer-123',
      status: 'active',
      startDate: new Date('2023-01-01'),
      endDate: new Date('2024-01-01'),
      createdAt: new Date('2023-01-01'),
      updatedAt: new Date('2023-01-01')
    };
  }

  private cancelSubscription(
    subscription: Subscription,
    cancelledAt: Date
  ): Subscription {
    return {
      ...subscription,
      status: 'cancelled',
      updatedAt: cancelledAt
    };
  }
}

