I'll explain the problem with Active Record models that embed business rules in ORM lifecycle hooks, then show how to refactor them using Clean Architecture principles.

## The Problem: Active Record with Embedded Business Rules

Here's an example of problematic code that violates Clean Architecture:

```typescript
// ❌ BAD: Domain logic mixed with persistence
class Order extends ActiveRecord {
  private _status: OrderStatus;
  private _totalAmount: number;
  private _items: OrderItem[];

  beforeSave(): void {
    // Business rule embedded in persistence lifecycle
    if (this._items.length === 0) {
      throw new Error("Order must have at least one item");
    }

    // Another business rule
    if (this._totalAmount < 0) {
      throw new Error("Order total cannot be negative");
    }

    // Status transition rules
    if (this._status === OrderStatus.PAID && this._totalAmount === 0) {
      this._status = OrderStatus.FULFILLED;
    }

    // Validation logic mixed with persistence
    this.validateItems();
  }

  private validateItems(): void {
    // Business logic mixed with persistence concerns
    for (const item of this._items) {
      if (item.quantity <= 0) {
        throw new Error("Item quantity must be positive");
      }
    }
  }
}
```

## The Solution: Clean Architecture Refactoring

### 1. Domain Layer (Pure Business Rules)

```typescript
// Domain Entities
export interface OrderItem {
  productId: string;
  quantity: number;
  price: number;
}

export enum OrderStatus {
  PENDING = 'pending',
  PAID = 'paid',
  FULFILLED = 'fulfilled',
  CANCELLED = 'cancelled'
}

export interface Order {
  id: string;
  items: OrderItem[];
  totalAmount: number;
  status: OrderStatus;
  createdAt: Date;
}

// Domain Errors
export class OrderValidationError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "OrderValidationError";
  }
}

export class OrderBusinessRuleError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "OrderBusinessRuleError";
  }
}

// Domain Services
export interface OrderValidator {
  validate(order: Order): Result<void, OrderValidationError>;
}

export interface OrderStatusService {
  calculateStatus(order: Order): Result<OrderStatus, OrderBusinessRuleError>;
}

// Pure Domain Logic
export class OrderBusinessRules {
  static validateItems(items: OrderItem[]): Result<void, OrderValidationError> {
    if (items.length === 0) {
      return Result.failure(new OrderValidationError("Order must have at least one item"));
    }

    for (const item of items) {
      if (item.quantity <= 0) {
        return Result.failure(new OrderValidationError("Item quantity must be positive"));
      }

      if (item.price < 0) {
        return Result.failure(new OrderValidationError("Item price cannot be negative"));
      }
    }

    return Result.success(undefined);
  }

  static validateTotalAmount(total: number): Result<void, OrderValidationError> {
    if (total < 0) {
      return Result.failure(new OrderValidationError("Order total cannot be negative"));
    }
    return Result.success(undefined);
  }

  static calculateStatus(order: Order): Result<OrderStatus, OrderBusinessRuleError> {
    // Business rules for status calculation
    if (order.status === OrderStatus.PAID && order.totalAmount === 0) {
      return Result.success(OrderStatus.FULFILLED);
    }

    return Result.success(order.status);
  }
}
